/* Promotional entry points. Existing functions and Gift state remain shared. */
const EASY={
 home:{title:'La casa ha una memoria.',lead:'Dimora la tiene insieme. Documenti, impianti, spese e persone utili: tutto al posto giusto, anche quando la casa cambia proprietario.',promise:'Parti dalle informazioni ricevute e continua la storia della tua casa.',actions:[['Conosci la tua casa','Impianti, manuali e garanzie: ritrova quello che serve.','know'],['Prenditene cura','Controlli, interventi e spese: meno cose da ricordare.','care'],['Condividi ciò che serve','Ricevi la memoria della casa e scegli cosa resta privato.','share']]},
 agency:{title:'Le chiavi. E una casa già organizzata.',lead:'Raccogli le informazioni una volta, prepara ciò che serve e consegna una memoria utile al nuovo proprietario.',promise:'Dai valore al tuo lavoro anche dopo la consegna delle chiavi.',actions:[['Raccogli la memoria','Un fascicolo chiaro, con ciò che hai e ciò che manca.','collect'],['Presenta la casa','Un dossier semplice, con i documenti giusti per chi compra.','present'],['Consegna la Home Gift','Prepara una casa che il cliente ritroverà tra le sue.','gift']]},
 admin:{title:'Un aggiornamento. Tutti nel contesto.',lead:'Impianti e documenti comuni, informazioni per le unità collegate, richieste e risposte facili da ritrovare.',promise:'Meno informazioni disperse, più chiarezza tra studio e proprietari.',actions:[['Conosci l’edificio','Ritrova impianti, documenti e attenzioni in un posto solo.','building'],['Aggiorna i proprietari','Pubblica ciò che serve, senza entrare nelle Home private.','publish'],['Segui le richieste','Una segnalazione, il suo contesto e una risposta consultabile.','requests']]}
};
function easyStart(){const cfg=EASY[state.role],pending=P.gifts.filter(g=>!g.accepted&&g.status==='Invito predisposto');return `<div class="easy-promise">${esc(cfg.promise)}</div><div class="easy-actions">${cfg.actions.map(([title,body,key],i)=>`<section class="easy-card"><span class="easy-number">0${i+1}</span><h2>${title}</h2><p>${body}</p>${pButton(title+' →','easy:'+key)}</section>`).join('')}</div>${state.role==='home'&&pending.length?'<p class="easy-arrival">Una casa ti aspetta: '+pending.length+' Home Gift da rivedere in “Condividi ciò che serve”.</p>':''}<section class="easy-benefits"><h2>Una casa. Tre benefici.</h2><div><p><strong>Agenzia</strong>Consegna le chiavi e una casa già organizzata.</p><p><strong>Proprietario</strong>Non ripartire da zero. Conserva, ricorda e scegli cosa condividere.</p><p><strong>Amministratore</strong>Aggiorna le persone giuste e ritrova richieste e risposte.</p></div></section><p class="easy-private">La memoria continua. Il controllo resta a chi la condivide.</p>`;}
function easyHub(key){const role=state.role;let title='',body='',actions='';
 const route=(label,page)=>pButton(label,'switch:'+role+':'+page,true);
 if(key==='know'){title='Conosci la tua casa';body='<p>Il manuale della caldaia quando serve. La planimetria quando fai un lavoro. Una garanzia da verificare prima di un acquisto.</p>'+V5.objects.slice(0,2).map(o=>pRow(o.name,o.room+' · documento collegato','easy-object:'+o.id,'Esplora')).join('')+'<p class="tiny">Pochi esempi qui; tutti i '+V5.objects.length+' oggetti e impianti restano nella tua casa.</p>';actions=route('Tutti gli impianti','Oggetti e impianti')+route('Documenti e manuali','Documenti')+route('Ambienti','Ambienti');}
 if(key==='care'){title='Prenditene cura';body='<p>Un controllo da ricordare, un intervento da conservare, una spesa da capire. La storia resta collegata alla casa.</p>'+pRow('Controllo caldaia','Esempio: scegli tu quando ricordarlo','switch:home:Attività','Vedi attività')+pRow('Quanto spendi per la casa','Registrazioni e lavori, senza ricostruire tutto a memoria','switch:home:Spese','Vedi spese')+pRow('Il tecnico da ritrovare','I contatti utili, accanto alle informazioni della casa','switch:home:Rubrica','Vedi contatti');actions=route('Storia della casa','Storia della casa');}
 if(key==='share'){title='Condividi ciò che serve';body='<p>La casa può arrivare con la sua memoria. Gli aggiornamenti comuni restano distinti dai tuoi documenti privati.</p>'+pRow('La tua nuova casa è pronta','Accetta la Gift: la casa e i documenti scelti compariranno tra Le mie case.','switch:home:Consegne ricevute','Rivedi consegne')+pRow('Le novità del condominio','Consulta gli aggiornamenti e ritrova le tue segnalazioni.','switch:home:Condominio','Apri condominio')+pRow('Scegli cosa condividere','Solo i contenuti selezionati. Le altre informazioni restano private.','switch:home:Condivisioni','Condividi');actions='';}
 if(key==='collect'){title='Raccogli la memoria';body='<p>Un fascicolo per casa. Documenti presenti, mancanti e da rivedere: sai subito il prossimo passo.</p>'+pRow(pProperty().name,'Esempio: planimetria presente, APE da raccogliere.','switch:agency:Checklist','Apri fascicolo');actions=route('Tutti i fascicoli','Fascicoli');}
 if(key==='present'){title='Presenta la casa';body='<p>Mostra il contesto della casa e prepara un dossier con ciò che il destinatario può ricevere. I documenti personali del venditore restano esclusi.</p>'+pRow('Una presentazione, due livelli','Anteprima della casa e selezione riservata da rivedere.','switch:agency:Dossier acquirente','Vedi dossier');}
 if(key==='gift'){title='Consegna la Home Gift';body='<p><strong>La tua nuova casa è pronta, con la sua memoria.</strong></p><p>Dai un nome alla casa, scegli documenti e impianti e prepara la consegna. Quando il proprietario accetta, la casa compare tra le sue, con i soli contenuti scelti.</p><p>Il valore dell’agenzia continua dopo le chiavi; la Home privata resta del proprietario.</p>';actions=pButton('Prepara la casa Gift','gift-start')+route('Le Gift del fascicolo','Home Gift');}
 if(key==='building'){title='Conosci l’edificio';body='<p>La fonte di un controllo e il documento di un impianto si ritrovano insieme. Le attenzioni restano visibili allo studio.</p>'+pProperty().technical.filter(t=>t.shared).slice(0,2).map(t=>pRow(t.name,t.doc+' · fonte dello studio','technical:'+t.id,'Esplora')).join('');actions=route('Memoria tecnica','Impianti e memoria')+route('Attenzioni e date','Scadenze')+route('Ipotesi di spesa','Budget e previsioni');}
 if(key==='publish'){title='Aggiorna i proprietari';body='<p>Seleziona un rapporto, controlla le unità collegate e pubblica un aggiornamento. Fonte e versione restano chiare; la Home privata non viene aperta allo studio.</p>'+pRow('Rapporto ascensore','Esempio di documento comune da pubblicare su scelta.','switch:admin:Pubblicazioni','Vedi pubblicazioni');actions=route('Collega le unità','Unità e accessi');}
 if(key==='requests'){title='Segui le richieste';body='<p>“La luce dell’ingresso è spenta”: una richiesta con edificio e unità, uno stato e una risposta che torna al proprietario.</p>'+pRow('Richiesta e risposta, insieme','Il proprietario ritrova l’aggiornamento sulla stessa segnalazione.','switch:admin:Segnalazioni','Apri segnalazioni');}
 pModal(title,body+'<p class="tiny">Esempi dimostrativi. Nessuna operazione reale.</p>',actions||pButton('Chiudi','close',true));
}
const easyBasePage=pageContent;
pageContent=function(){return (state.role==='home'&&state.page==='Casa'||state.role!=='home'&&state.page==='Panoramica')?easyStart():easyBasePage();};
const easyBaseAction=pAction;
pAction=function(a,args){if(a==='easy'){easyHub(args[0]);return;}if(a==='easy-object'){vObject(args.join(':'));return;}return easyBaseAction(a,args);};
const easyBaseWorkspace=workspace;
workspace=function(){if(state.role!=='home'&&pProperty()?.giftHome)pSelect(pProperty().sourceProperty);let html=easyBaseWorkspace(),start=state.role==='home'?state.page==='Casa':state.page==='Panoramica';if(start){const cfg=EASY[state.role];html=html.replace(/<div class="pagehead">[\s\S]*?<\/div><\/div>/,`<div class="pagehead easy-head"><div><div class="eyebrow">${esc(state.selected)} · ${esc(roles[state.role].name)}</div><h1>${cfg.title}</h1><p>${cfg.lead}</p></div></div>`);}const asideEnd=html.indexOf('</aside>'),first=html.indexOf('<button class="navitem'),foot=html.indexOf('<div class="sidefoot">');if(first>0&&foot>first&&foot<asideEnd){const nav=html.slice(first,foot).replace(/<details class="simple-more"><summary>Altre funzioni<\/summary>/g,'').replace(/<\/details>/g,'');const firstEnd=nav.indexOf('</button>')+9;html=html.slice(0,first)+nav.slice(0,firstEnd)+'<details class="simple-more"><summary>Tutte le funzioni</summary>'+nav.slice(firstEnd)+'</details>'+html.slice(foot);}return html;};
render();

